use super::helpers::run_prints;
fn run_c(src: &str) -> Vec<String> { run_prints(&format!("#include <stdio.h>\n{}", src)) }

#[test] fn cnd_init_destroy() { assert_eq!(run_c("#include <threads.h>\nint main() { cnd_t c; if (cnd_init(&c) == thrd_success) { cnd_destroy(&c); printf(\"ok\"); } return 0; }"), vec!["ok"]); }
#[test] fn cnd_signal_no_waiters() { assert_eq!(run_c("#include <threads.h>\nint main() { cnd_t c; if (cnd_init(&c) == thrd_success) { cnd_signal(&c); cnd_destroy(&c); printf(\"ok\"); } return 0; }"), vec!["ok"]); }
#[test] fn cnd_broadcast_no_waiters() { assert_eq!(run_c("#include <threads.h>\nint main() { cnd_t c; if (cnd_init(&c) == thrd_success) { cnd_broadcast(&c); cnd_destroy(&c); printf(\"ok\"); } return 0; }"), vec!["ok"]); }
#[test] fn cnd_wait_signal_basic() { assert_eq!(run_c("#include <threads.h>\nmtx_t m; cnd_t c; int ready = 0;\nint worker(void *arg) { mtx_lock(&m); ready = 1; cnd_signal(&c); mtx_unlock(&m); return 0; }\nint main() { mtx_init(&m, mtx_plain); cnd_init(&c); thrd_t t; thrd_create(&t, worker, NULL); mtx_lock(&m); while(!ready) cnd_wait(&c, &m); mtx_unlock(&m); thrd_join(t, NULL); printf(\"ok\"); mtx_destroy(&m); cnd_destroy(&c); return 0; }"), vec!["ok"]); }
#[test] fn cnd_timedwait_timeout() { assert_eq!(run_c("#include <threads.h>\n#include <time.h>\nint main() { mtx_t m; cnd_t c; mtx_init(&m, mtx_timed); cnd_init(&c); mtx_lock(&m); struct timespec ts; timespec_get(&ts, TIME_UTC); int res = cnd_timedwait(&c, &m, &ts); mtx_unlock(&m); printf(\"%d\", res == thrd_timedout); mtx_destroy(&m); cnd_destroy(&c); return 0; }"), vec!["1"]); } // time in past or zero causes immediate timeout
